Task: Push the orange puck so that its centre ends up inside the green circle. The puck is too wide to grasp.

Skill code (numbered):
  1| # skill module
  2| import math
  3| import numpy as np
  4| 
  5| # ---------- configuration ----------
  6| MAX_PUSH_ATTEMPTS = 8          # total pushes we will try
  7| MAX_PUSH_PER_STEP = 0.015      # 1.5 cm per step – fits the narrow corridor
  8| CLEARANCE_ABOVE = 0.018        # 1.8 cm clearance to avoid side collisions
  9| MIN_APPROACH_Z = 0.014         # lowest safe height
 10| SLOW_SPEED = 0.05              # m/s, used everywhere
 11| 
 12| def run(robot):
 13|     # ---------- 1. perception ----------
 14|     obs = robot.observe()
 15|     puck = obs["objects"]["puck"]
 16|     target = obs["fixtures"]["target"]
 17|     puck_pos = np.array(puck["pos"], dtype=float)          # centre of puck
 18|     target_pos = np.array(target["pos"][:2], dtype=float)  # (x, y) of zone centre
 19|     target_radius = target["radius"]
 20| 
 21|     # If puck already inside the target, we are done
 22|     if np.linalg.norm(puck_pos[:2] - target_pos) < target_radius:
 23|         return True
 24| 
 25|     # ---------- 2. approach from above ----------
 26|     # Compute a small offset toward the target to avoid side contacts
 27|     delta_xy = target_pos - puck_pos[:2]
 28|     remaining_xy = np.linalg.norm(delta_xy)
 29|     if remaining_xy > 1e-6:
 30|         offset_dir = delta_xy / remaining_xy
 31|         offset = 0.02 * offset_dir               # ~2 cm offset, safe margin
 32|     else:
 33|         offset_dir = np.array([1.0, 0.0])
 34|         offset = np.array([0.02, 0.0])
 35| 
 36|     approach_xy = puck_pos[:2] + offset
 37|     approach_z = puck_pos[2] + CLEARANCE_ABOVE
 38|     # Clamp to the safe workspace
 39|     approach_z = max(approach_z, MIN_APPROACH_Z)
 40|     approach_z = min(approach_z, 0.26)
 41| 
 42|     # Try to move to the approach pose; if blocked, raise height a bit and retry
 43|     for _ in range(2):
 44|         try:
 45|             robot.move_to(approach_xy[0], approach_xy[1], approach_z, speed=SLOW_SPEED)
 46|             break
 47|         except Exception:
 48|             approach_z = min(approach_z + 0.005, 0.26)
 49|             robot.move_to(approach_xy[0], approach_xy[1], approach_z, speed=SLOW_SPEED)
 50| 
 51|     # ---------- 3. descend to touch the puck top ----------
 52|     # Fingertips sit ~1.25 cm below the tool point; lower by that amount
 53|     for _ in range(2):
 54|         try:
 55|             robot.move_by(dz=-0.0125, speed=SLOW_SPEED)
 56|             break
 57|         except Exception:
 58|             # Lift a little and try the descent again
 59|             robot.move_by(dz=0.005, speed=SLOW_SPEED)
 60|             robot.move_by(dz=-0.0125, speed=SLOW_SPEED)
 61| 
 62|     # ---------- 4. iterative pushing ----------
 63|     for _ in range(MAX_PUSH_ATTEMPTS):
 64|         # Re‑observe to get the current puck pose (it may have moved)
 65|         obs = robot.observe()
 66|         puck = obs["objects"]["puck"]
 67|         puck_pos = np.array(puck["pos"], dtype=float)
 68|         delta = target_pos - puck_pos[:2]
 69|         dist = np.linalg.norm(delta)
 70| 
 71|         # Success if we are already inside the target radius
 72|         if dist < target_radius:
 73|             break
 74| 
 75|         # Determine a safe push step (never exceed what remains)
 76|         push_step = min(MAX_PUSH_PER_STEP, dist)
 77|         if push_step <= 0:
 78|             break
 79|         direction = delta / dist
 80| 
 81|         # Attempt the push; on blockage we lift, re‑observe and continue
 82|         try:
 83|             robot.move_by(
 84|                 dx=direction[0] * push_step,
 85|                 dy=direction[1] * push_step,
 86|                 speed=SLOW_SPEED
 87|             )
 88|         except Exception:
 89|             # Lift back to approach height to reset the gripper
 90|             try:
 91|                 robot.move_to(puck_pos[0], puck_pos[1], approach_z, speed=SLOW_SPEED)
 92|             except Exception:
 93|                 pass
 94|             continue   # try the next push attempt
 95| 
 96|         # After a successful push, lift back up to the safe approach height
 97|         try:
 98|             robot.move_to(puck_pos[0], puck_pos[1], approach_z, speed=SLOW_SPEED)
 99|         except Exception:
100|             pass
101| 
102|     # ---------- 5. final verification ----------
103|     final_obs = robot.observe()
104|     final_puck = np.array(final_obs["objects"]["puck"]["pos"], dtype=float)
105|     final_dist = np.linalg.norm(final_puck[:2] - target_pos)
106| 
107|     return final_dist < target_radius

